1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { createPortal } from "react-dom";
5	
6	/**
7	 * Full-screen overlay shown while createFreeMinecraftServer's server action is
8	 * pending. This can genuinely take up to ~180s for a plugin-heavy preset (see
9	 * FREEMC_PLUGIN_READY_TIMEOUT_MS in lib/free-minecraft-control.ts) — without
10	 * this, the button just said "Creating…" and the page otherwise looked frozen
11	 * for that whole window, which reads as broken rather than working. The
12	 * messages below are deliberately generic/sequential, not tied to a real
13	 * server-reported step — the action is one blocking call with no progress
14	 * stream, so claiming precise live status would be dishonest. They're framed
15	 * as "roughly what's happening," not a real-time log.
16	 *
17	 * Per-step durations are modeled on a real captured boot log for a
18	 * plugin-heavy (SkyBlock) create — confirmed live 2026-09-02, itzg/
19	 * minecraft-server container start to "Done": ~8s init/resolve, ~10s
20	 * downloading the server jar + plugin jars, ~10s copying configs/writing
21	 * server.properties + default config downloads, ~10s downloading the
22	 * Minecraft jar itself + applying patches + starting Bukkit, ~10s JVM boot +
23	 * plugin init + the session-server environment check, then the single
24	 * biggest chunk — ~23s preparing the base world's spawn area alone, plus
25	 * another ~19s for the plugin's own world (e.g. IridiumSkyblock's island) —
26	 * then plugin enable + RCON/final setup. Simpler presets finish well before
27	 * reaching the later steps, which is fine — the sequence just stops
28	 * advancing the moment the action resolves.
29	 */
30	const STEPS: { label: string; durationMs: number }[] = [
31	  { label: "Reserving your world…", durationMs: 5_000 },
32	  { label: "Fetching server files…", durationMs: 10_000 },
33	  { label: "Installing plugins…", durationMs: 10_000 },
34	  { label: "Writing world settings…", durationMs: 10_000 },
35	  { label: "Booting the server…", durationMs: 10_000 },
36	  { label: "Generating your world…", durationMs: 30_000 },
37	  { label: "Setting up your island…", durationMs: 20_000 },
38	  { label: "Waking everything up…", durationMs: 15_000 },
39	  { label: "Almost there…", durationMs: Infinity },
40	];
41	
42	export function FreeMinecraftLoader() {
43	  const [mounted, setMounted] = useState(false);
44	  const [stepIndex, setStepIndex] = useState(0);
45	
46	  useEffect(() => {
47	    setMounted(true);
48	  }, []);
49	
50	  useEffect(() => {
51	    if (stepIndex >= STEPS.length - 1) return;
52	    const id = setTimeout(() => setStepIndex((i) => Math.min(i + 1, STEPS.length - 1)), STEPS[stepIndex].durationMs);
53	    return () => clearTimeout(id);
54	  }, [stepIndex]);
55	
56	  if (!mounted) return null;
57	
58	  return createPortal(
59	    <div
60	      className="fixed inset-0 z-[100] flex flex-col items-center justify-center gap-8 bg-[#05060d]/92 p-6 backdrop-blur-md"
61	      role="status"
62	      aria-live="polite"
63	    >
64	      <div className="flex w-full max-w-md flex-col items-center gap-7 rounded-3xl border border-white/10 bg-white/[0.04] px-10 py-12 shadow-2xl shadow-black/50">
65	        <CreeperScene />
66	        <div className="flex flex-col items-center gap-2 text-center">
67	          <p className="text-base font-semibold text-slate-100">{STEPS[stepIndex].label}</p>
68	          <p className="max-w-xs text-sm text-slate-500">
69	            Some game types take a couple of minutes to fully set up — this page will move on the moment it&apos;s ready.
70	          </p>
71	        </div>
72	        <div className="flex gap-1.5">
73	          {STEPS.map((_, i) => (
74	            <span
75	              key={i}
76	              className={`h-1.5 w-1.5 rounded-full transition-colors duration-500 ${
77	                i <= stepIndex ? "bg-brand-400" : "bg-white/10"
78	              }`}
79	            />
80	          ))}
81	        </div>
82	      </div>
83	    </div>,
84	    document.body,
85	  );
86	}
