88	/** 8x8 pixel-grid creeper face: 0 = skin, 1 = dark face marking. */
89	const CREEPER_FACE = [
90	  0, 0, 0, 0, 0, 0, 0, 0,
91	  0, 1, 1, 0, 0, 1, 1, 0,
92	  0, 1, 1, 0, 0, 1, 1, 0,
93	  0, 0, 0, 1, 1, 0, 0, 0,
94	  0, 0, 1, 1, 1, 1, 0, 0,
95	  0, 1, 1, 0, 0, 1, 1, 0,
96	  0, 1, 1, 0, 0, 1, 1, 0,
97	  0, 1, 1, 1, 1, 1, 1, 0,
98	];
99	
100	const PARTICLE_ANGLES = [0, 45, 90, 135, 180, 225, 270, 315];
101	
102	/** Creeper head that charges/hisses, then flashes and "explodes" outward in a loop, pure inline SVG. */
103	function CreeperScene() {
104	  const cell = 13;
105	  const gridSize = cell * 8;
106	  const viewSize = 220;
107	  const origin = (viewSize - gridSize) / 2;
108	  const center = viewSize / 2;
109	
110	  return (
111	    <svg
112	      viewBox={`0 0 ${viewSize} ${viewSize}`}
113	      className="h-56 w-56 [image-rendering:pixelated]"
114	      style={{ shapeRendering: "crispEdges" }}
115	      aria-hidden
116	    >
117	      <style>{`
118	        @keyframes cp-glow {
119	          0%, 60% { opacity: 0; transform: scale(0.6); }
120	          66% { opacity: 0.55; transform: scale(1); }
121	          88% { opacity: 0; transform: scale(1.6); }
122	          100% { opacity: 0; transform: scale(0.6); }
123	        }
124	        @keyframes cp-hiss {
125	          0%, 4% { transform: scale(1) rotate(0deg); filter: brightness(1) saturate(1); opacity: 1; }
126	          8% { transform: scale(1.015) rotate(-1.5deg); }
127	          12% { transform: scale(1) rotate(1.5deg); }
128	          16% { transform: scale(1.015) rotate(-1.5deg); }
129	          20%, 55% { transform: scale(1) rotate(0deg); filter: brightness(1) saturate(1); opacity: 1; }
130	          60% { transform: scale(1.06); filter: brightness(1.2) saturate(1); }
131	          65% { transform: scale(1.2); filter: brightness(2.2) saturate(0.3); }
132	          70% { transform: scale(1.55); filter: brightness(4) saturate(0); opacity: 0.85; }
133	          78% { transform: scale(1.9); filter: brightness(5) saturate(0); opacity: 0; }
134	          100% { transform: scale(1) rotate(0deg); filter: brightness(1) saturate(1); opacity: 1; }
135	        }
136	        @keyframes cp-shock {
137	          0%, 62% { transform: scale(0); opacity: 0; }
138	          67% { transform: scale(1); opacity: 0.9; }
139	          90% { transform: scale(5.5); opacity: 0; }
140	          100% { transform: scale(0); opacity: 0; }
141	        }
142	        @keyframes cp-particle {
143	          0%, 63% { opacity: 0; transform: translate(0px, 0px) scale(1); }
144	          68% { opacity: 1; }
145	          92% { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(0.25); }
146	          100% { opacity: 0; }
147	        }
148	        .cp-glow { transform-box: fill-box; transform-origin: 50% 50%; animation: cp-glow 2.6s ease-out infinite; }
149	        .cp-face { transform-box: fill-box; transform-origin: 50% 50%; animation: cp-hiss 2.6s cubic-bezier(.36,.07,.19,.97) infinite; }
150	        .cp-shock { transform-box: fill-box; transform-origin: 50% 50%; animation: cp-shock 2.6s ease-out infinite; }
151	        .cp-particle { animation: cp-particle 2.6s ease-out infinite; }
152	        @media (prefers-reduced-motion: reduce) {
153	          .cp-glow, .cp-face, .cp-shock, .cp-particle { animation: none; }
154	          .cp-glow, .cp-shock { opacity: 0; }
155	        }
156	      `}</style>
157	
158	      {/* soft impact glow behind the face, spikes at explosion */}
159	      <circle className="cp-glow" cx={center} cy={center} r={70} fill="#eafff0" opacity="0" />
160	
161	      {/* shockwave ring */}
162	      <circle className="cp-shock" cx={center} cy={center} r={22} fill="none" stroke="#f4fff6" strokeWidth="4" opacity="0" />
163	
164	      {/* debris/spark particles */}
165	      {PARTICLE_ANGLES.map((deg, i) => {
166	        const rad = (deg * Math.PI) / 180;
167	        const dist = 78 + (i % 3) * 10;
168	        const dx = Math.cos(rad) * dist;
169	        const dy = Math.sin(rad) * dist;
170	        const colors = ["#6cb52d", "#4c8e2f", "#e8e8e8", "#3a3a3a"];
171	        const size = 6 + (i % 3) * 2;
172	        return (
173	          <rect
174	            key={deg}
175	            className="cp-particle"
176	            x={center - size / 2}
177	            y={center - size / 2}
178	            width={size}
179	            height={size}
180	            fill={colors[i % colors.length]}
181	            style={
182	              {
183	                "--dx": `${dx}px`,
184	                "--dy": `${dy}px`,
185	                animationDelay: `${i * 0.02}s`,
186	              } as React.CSSProperties
187	            }
188	          />
189	        );
190	      })}
191	
192	      {/* the creeper face itself */}
193	      <g className="cp-face">
194	        {CREEPER_FACE.map((v, i) => {
195	          if (v === 0) return null;
196	          const col = i % 8;
197	          const row = Math.floor(i / 8);
198	          return (
199	            <rect
200	              key={i}
201	              x={origin + col * cell}
202	              y={origin + row * cell}
203	              width={cell}
204	              height={cell}
205	              fill="#161616"
206	            />
207	          );
208	        })}
209	        <rect x={origin} y={origin} width={gridSize} height={gridSize} fill="none" />
210	        {/* skin fill sits beneath the marking squares via paint order */}
211	        <rect
212	          x={origin}
213	          y={origin}
214	          width={gridSize}
215	          height={gridSize}
216	          fill="#5fae3b"
217	          style={{ paintOrder: "fill" }}
218	        />
219	        {CREEPER_FACE.map((v, i) => {
220	          if (v === 0) return null;
221	          const col = i % 8;
222	          const row = Math.floor(i / 8);
223	          return (
224	            <rect
225	              key={`mark-${i}`}
226	              x={origin + col * cell}
227	              y={origin + row * cell}
228	              width={cell}
229	              height={cell}
230	              fill="#161616"
231	            />
232	          );
233	        })}
234	      </g>
235	    </svg>
236	  );
237	}
