3	import { useEffect, useRef, useState } from "react";
4	import { createPortal } from "react-dom";
5	import { RevealPassword, CopyText } from "@/components/customer/ServerAccess";
6	
7	/**
8	 * The Hostinger-style "your order is being set up" interstitial — shown full
9	 * screen right after a customer pays/deploys, while the VM is still
10	 * PENDING/PROVISIONING, then a one-time success card once it flips to
11	 * RUNNING. Deliberately built as a pure overlay on TOP of the existing
12	 * server-detail page rather than a new route: the page underneath keeps
13	 * rendering (and keeps refreshing via the existing `<AutoRefresh />`) exactly
14	 * as it always has, so this component only ever needs to react to props that
15	 * are already being recomputed every 5s — no new polling loop, no new server
16	 * action.
17	 *
18	 * Visibility rules (see the effect below for the full state machine):
19	 *   - Shows the "provisioning" phase whenever the server is in a transitional
20	 *     status. Sets a sessionStorage flag so a REFRESH mid-provision still
21	 *     shows it (not just the initial mount).
22	 *   - Shows "success" the moment that flag is set AND the status flips to
23	 *     RUNNING — OR, for the case where the server was ALREADY done by the
24	 *     time this page first loaded (real orders provision in under two
25	 *     minutes, but this platform's SANDBOX mode completes instantly), when
26	 *     the URL carries the `purchase=1` marker `reportPurchase` already stamps
27	 *     onto every real paid-order redirect.
28	 *   - Never shown for a customer just casually revisiting an old, already-
29	 *     running server — that's the whole reason for the two gates above
30	 *     instead of "status === RUNNING".
31	 *   - Once dismissed, stays dismissed for this server (sessionStorage),
32	 *     surviving a refresh.
33	 */
34	export function ProvisioningOverlay({
35	  serverId,
36	  status,
37	  transitional,
38	  justPaid,
39	  provisionError,
40	  productLabel,
41	  hostname,
42	  connectAddress,
43	  planName,
44	  osName,
45	  rootPassword,
46	  rootPasswordLabel,
47	  extraInfo,
48	  readyStatus = "RUNNING",
49	  liveStep = null,
50	  liveStepActive = false,
51	  dashboardHref,
52	}: {
53	  serverId: string;
54	  status: string;
55	  transitional: boolean;
56	  /**
57	   * True only when THIS request's URL carried `?purchase=1` — read server-side
58	   * from `searchParams` and passed down as a plain prop, not re-derived from
59	   * `window.location.search` on the client. `app/dashboard/layout.tsx`'s
60	   * PurchaseTracker also reads `?purchase=1` (to fire the conversion pixel)
61	   * and then strips it via `router.replace()`; a client-side read here loses
62	   * that race unpredictably (confirmed in testing — a lazy `useState`
63	   * initializer still lost it under the App Router's RSC re-render on
64	   * navigation). The server captured the true value from the original
65	   * request before any client-side history mutation could touch it.
66	   */
67	  justPaid: boolean;
68	  provisionError?: string | null;
69	  /** "server" | "game server" | "hosting account" | etc — used in copy ("Your ... is live!"). */
70	  productLabel: string;
71	  hostname: string;
72	  /** The connect string to show, e.g. "ssh root@1.2.3.4" or "1.2.3.4:25565" — null while not yet assigned. */
73	  connectAddress: string | null;
74	  planName: string;
75	  osName: string | null;
76	  rootPassword: string | null;
77	  /** Label for the `rootPassword` row — defaults to "Root password" (VPS/game). Shared
78	   *  Hosting has no root password; pass "SFTP password" there instead of inventing a
79	   *  VPS-shaped field that doesn't exist for that product. */
80	  rootPasswordLabel?: string;
81	  /** Extra product-specific rows appended to the success card's info panel (e.g.
82	   *  Shared Hosting's "SFTP username" / "Website" — fields a VPS has no analogue
83	   *  for), rather than forcing every product into VPS-shaped fields. */
84	  extraInfo?: { label: string; value: string; href?: string }[];
85	  /** The status value that means "done, show the success card" — "RUNNING" for a
86	   *  VPS/game server, "ACTIVE" for a Shared Hosting account. */
87	  readyStatus?: string;
88	  /** Real (never fake/invented) current-step label, e.g. "Cloning your server…" or
89	   *  "Installing WordPress…" — sourced from lib/provisioning-step.ts. Replaces the
90	   *  cosmetic time-based cycling text in the provisioning view when present; null
91	   *  falls back to that cosmetic text (no real signal available yet). */
92	  liveStep?: string | null;
93	  /** True while a real, product-specific step is still in progress even though
94	   *  `transitional` (account/server status) has already gone false — e.g. Shared
95	   *  Hosting's account is ACTIVE but a just-ordered WordPress install is still
96	   *  running as a queued task. Only ever extends the provisioning view while this
97	   *  session was already watching (or just paid) — see the effect below — so a
98	   *  LATER, casual action (installing an app months on) never hijacks the screen. */
99	  liveStepActive?: boolean;
100	  /** Where "Go to your server" sends them — normally just this same page. */
101	  dashboardHref: string;
102	}) {
103	  const storageKey = `nxeon:overlay:${serverId}`;
104	  const [phase, setPhase] = useState<"hidden" | "provisioning" | "success">("hidden");
105	  const mountedAtRef = useRef<number | null>(null);
106	  // Real infra provisions in well under this — it's purely a perceived-progress
107	  // floor so the animation never flashes by unreadably fast (e.g. SANDBOX mode,
108	  // which completes instantly), not a claim about how long the real work takes.
109	  const MIN_PROVISIONING_MS = 3200;
110	
111	  useEffect(() => {
112	    let watching = false;
113	    try {
114	      watching = sessionStorage.getItem(storageKey) === "watching";
115	    } catch {
116	      /* storage disabled — degrade to "never show" rather than guess */
117	    }
118	
119	    if (transitional) {
120	      if (mountedAtRef.current == null) mountedAtRef.current = Date.now();
121	      setPhase("provisioning");
122	      try {
123	        sessionStorage.setItem(storageKey, "watching");
124	      } catch {
125	        /* ignore */
126	      }
127	      return;
128	    }
129	
130	    // Not transitional anymore (by the base status alone). Before deciding this is
131	    // done, check for a real, product-specific follow-on step still running — e.g.
132	    // Shared Hosting's account just flipped ACTIVE but a WordPress install queued
133	    // at order time is still processing. Gated on watching/justPaid, same as the
134	    // block above: this must never resurrect the full-screen takeover for a LATER,
135	    // casual action (installing an app months after purchase) — only for a follow-
136	    // on step that belongs to the SAME order this session was already watching.
137	    if (liveStepActive && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
138	      setPhase("provisioning");
139	      return;
140	    }
141	
142	    // Only earn a success screen if we were either actively watching this order
143	    // provision, or just landed here from a real paid checkout (the
144	    // sandbox-instant-complete case).
145	    if (status === readyStatus && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
146	      const elapsed = mountedAtRef.current ? Date.now() - mountedAtRef.current : MIN_PROVISIONING_MS;
147	      const wait = Math.max(0, MIN_PROVISIONING_MS - elapsed);
148	      const t = setTimeout(() => setPhase("success"), wait);
149	      return () => clearTimeout(t);
150	    }
151	    // ERROR or anything else while we were watching: hand off to the page's
152	    // own ProvisionErrorBanner rather than duplicating retry UI here.
153	    setPhase("hidden");
154	    // eslint-disable-next-line react-hooks/exhaustive-deps
155	  }, [transitional, status, liveStepActive, readyStatus]);
156	
157	  function dismiss() {
158	    try {
159	      sessionStorage.setItem(storageKey, "dismissed");
160	    } catch {
161	      /* ignore */
162	    }
163	    setPhase("hidden");
164	  }
165	
166	  if (phase === "hidden") return null;
167	
168	  // Portaled to document.body — every dashboard page's <main> (components/
169	  // portal/Shell.tsx) carries a permanent `transform` from its own entrance
170	  // animation (animate-fade-up ends on translateY(0), which a CSS animation
171	  // with `both` fill-mode keeps applied forever, not just during the
172	  // transition). Per spec, ANY transform on an ancestor — even that settled
173	  // identity value — creates a new containing block for `position: fixed`
174	  // descendants, so `fixed inset-0` here resolved against that ancestor's
175	  // box instead of the real viewport, clipping most of this overlay
176	  // off-screen (found live in production via the identical bug in
177	  // AddFundsPaymentModal.tsx, which uses the same fix).
178	  return createPortal(
179	    <div className="fixed inset-0 z-[100] flex items-center justify-center overflow-y-auto bg-navy-950/90 p-4 backdrop-blur-md">
180	      <div className="card glow-brand relative w-full max-w-md motion-safe:animate-panel-in">
181	        {phase === "provisioning" ? (
182	          <ProvisioningView productLabel={productLabel} hostname={hostname} liveStep={liveStep} />
183	        ) : (
184	          <SuccessView
185	            productLabel={productLabel}
186	            hostname={hostname}
187	            connectAddress={connectAddress}
188	            planName={planName}
189	            osName={osName}
190	            rootPassword={rootPassword}
191	            rootPasswordLabel={rootPasswordLabel}
192	            extraInfo={extraInfo}
193	            onDismiss={dismiss}
194	            dashboardHref={dashboardHref}
195	          />
196	        )}
197	      </div>
198	    </div>,
199	    document.body,
200	  );
201	}
