224	  // doesn't read as a frozen screen. Skipped entirely once `liveStep` is real.
225	  const [stepIndex, setStepIndex] = useState(0);
226	  useEffect(() => {
227	    if (liveStep) return;
228	    const id = setInterval(() => {
229	      setStepIndex((i) => Math.min(i + 1, PROVISION_STEPS.length - 1));
230	    }, 3500);
