247	        </svg>
248	        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" className="relative h-8 w-8 text-brand-200">
249	          <rect x="3" y="4" width="18" height="7" rx="1.5" />
250	          <rect x="3" y="13" width="18" height="7" rx="1.5" />
251	          <path d="M7 7.5h.01M7 16.5h.01" />
