const TIER_COLORS: Record<string, { icon: string; badge: string }> = {
  starter: { icon: "bg-gradient-to-br from-brand-500/30 to-brand-600/10 text-brand-300", badge: "border-brand-500/40 bg-brand-500/10 text-brand-300" },
  business: { icon: "bg-gradient-to-br from-teal-500/30 to-emerald-600/10 text-teal-300", badge: "border-teal-500/40 bg-teal-500/10 text-teal-300" },
  pro: { icon: "bg-gradient-to-br from-orange-500/30 to-orange-600/10 text-orange-300", badge: "border-orange-500/40 bg-orange-500/10 text-orange-300" },
};
const TIER_COLOR_RAMP = [
  { icon: "bg-gradient-to-br from-brand-500/30 to-brand-600/10 text-brand-300", badge: "border-brand-500/40 bg-brand-500/10 text-brand-300" },
  { icon: "bg-gradient-to-br from-accent-blue/30 to-blue-600/10 text-blue-300", badge: "border-blue-500/40 bg-blue-500/10 text-blue-300" },
  { icon: "bg-gradient-to-br from-teal-500/30 to-emerald-600/10 text-teal-300", badge: "border-teal-500/40 bg-teal-500/10 text-teal-300" },
  { icon: "bg-gradient-to-br from-orange-500/30 to-orange-600/10 text-orange-300", badge: "border-orange-500/40 bg-orange-500/10 text-orange-300" },
];
function tierColor(a: Pick<HostingAccountView, "planSlug" | "planSortOrder">) {
  return TIER_COLORS[a.planSlug] ?? TIER_COLOR_RAMP[a.planSortOrder % TIER_COLOR_RAMP.length];
}


