121	          <stop offset="1" stopColor="#121a34" />
122	        </linearGradient>
123	        <linearGradient id="hubFront" x1="0" y1="0" x2="0" y2="1">
124	          <stop offset="0" stopColor="#131c38" />
125	          <stop offset="1" stopColor="#0b1226" />
126	        </linearGradient>
127	        <linearGradient id="hubSide" x1="0" y1="0" x2="0" y2="1">
128	          <stop offset="0" stopColor="#0d1428" />
129	          <stop offset="1" stopColor="#080d1c" />
130	        </linearGradient>
131	        <linearGradient id="hubEdge" x1="0" y1="0" x2="1" y2="1">
132	          <stop offset="0" stopColor="#8a70fb" />
133	          <stop offset="1" stopColor="#22d3ee" />
134	        </linearGradient>
135	        <radialGradient id="hubGlow" cx="0.5" cy="0.5" r="0.5">
136	          <stop offset="0" stopColor="#6f47f5" stopOpacity="0.55" />
137	          <stop offset="1" stopColor="#6f47f5" stopOpacity="0" />
138	        </radialGradient>
139	      </defs>
140	
141	      {/* ground glow */}
142	      <ellipse cx="160" cy="256" rx="120" ry="30" fill="url(#hubGlow)" />
143	
144	      {blades.map((b) => {
145	        // iso projection: each blade sits 46px higher than the last.
146	        const oy = 190 - b * 46;
147	        const dx = 120; // half-width along the iso X
148	        const dz = 60; // depth along iso Y
149	        const h = 26; // blade thickness (front face)
150	        const cx = 160;
151	        // key points of the top rhombus
152	        const top = `${cx},${oy - dz / 2} ${cx + dx},${oy} ${cx},${oy + dz / 2} ${cx - dx},${oy}`;
153	        const led = b === 1 ? "#22d3ee" : "#8a70fb";
154	        return (
155	          <g key={b}>
156	            {/* top face */}
157	            <polygon points={top} fill="url(#hubTop)" stroke="url(#hubEdge)" strokeWidth="1.25" strokeOpacity="0.6" />
158	            {/* front-left face */}
159	            <polygon
160	              points={`${cx - dx},${oy} ${cx},${oy + dz / 2} ${cx},${oy + dz / 2 + h} ${cx - dx},${oy + h}`}
161	              fill="url(#hubFront)"
162	            />
163	            {/* front-right face */}
164	            <polygon
165	              points={`${cx},${oy + dz / 2} ${cx + dx},${oy} ${cx + dx},${oy + h} ${cx},${oy + dz / 2 + h}`}
166	              fill="url(#hubSide)"
167	            />
168	            {/* glowing seam along the front bottom edge */}
169	            <polyline
170	              points={`${cx - dx},${oy + h} ${cx},${oy + dz / 2 + h} ${cx + dx},${oy + h}`}
171	              stroke="url(#hubEdge)"
172	              strokeWidth="1.5"
173	              strokeOpacity="0.85"
174	              fill="none"
175	            />
176	            {/* drive slots on the left face */}
177	            {[0, 1, 2].map((s) => (
178	              <line
179	                key={s}
